def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Adjacent matching markers on opposite horizontal edges launch inward rays.
    pairs = []
    marked = set()
    for r, dr in ((0, 1), (h - 1, -1)):
        for c in range(w - 1):
            if grid[r][c] != bg and grid[r][c] == grid[r][c + 1]:
                pairs.append((r, c, dr))
                marked.update(((r, c), (r, c + 1)))

    if pairs:
        sources = [(r, c, grid[r][c])
                   for r in range(h) for c in range(w)
                   if grid[r][c] != bg and (r, c) not in marked]
        if not sources:
            return out
        ray_color = sources[0][2]
        for r, c, _ in sources:
            out[r][c] = 4

        for r, c, dr in pairs:
            rr = r + dr
            while 0 <= rr < h:
                if grid[rr][c] != bg:
                    break
                out[rr][c] = ray_color
                rr += dr
        return out

    # Opposing vertical border segments project horizontal rays and their
    # corresponding rows across the other segment.
    def run_at_edge(col):
        vals = [grid[r][col] for r in range(h)]
        runs = []
        r = 0
        while r < h:
            if vals[r] == bg:
                r += 1
                continue
            start, color = r, vals[r]
            while r + 1 < h and vals[r + 1] == color:
                r += 1
            runs.append((start, r, color))
            r += 1
        return max(runs, key=lambda x: x[1] - x[0]) if runs else None

    left = run_at_edge(0)
    right = run_at_edge(w - 1)
    if left and right and left[2] == right[2]:
        offset = right[0] - left[0]
        for r in range(right[0], right[1] + 1):
            for c in range(1, w - 1):
                color = grid[r][c]
                if color == bg:
                    continue
                out[r][c] = 4
                for cc in range(c + 1, w - 1):
                    out[r][cc] = color
                mirror_r = r - offset
                if 0 <= mirror_r < h:
                    for cc in range(1, w):
                        out[mirror_r][cc] = color

    return out
